(function(root){
'use strict';
const G=root.Game,clamp=n=>Math.max(0,Math.min(100,n));
G.LEGACY_FUNDS=[
 {id:'crew',name:'Folkene skal ha en framtid',speaker:'Raggen',rate:.10,text:'Et varig lagfond trener to eksisterende folk per kvartal, gir +4 lojalitet og −5 slitasje. Et sammensveiset lag styrker deg mot Bjørnar.'},
 {id:'city',name:'Byen får en del av gevinsten',speaker:'Ada',rate:.12,text:'Åpne lokaler og lokale arbeidsplasser gir +4 støtte og +4 innflytelse per kvartal. Ved 20 millioner i fondet kan én ekstra region ledes lokalt.'},
 {id:'counsel',name:'Avtalene skal tåle dagslys',speaker:'Nora',rate:.08,text:'Uavhengig gjennomgang gir +4 forsvar og demper bevispress med 2 per kvartal. Dokumentasjonen gir større rom i oppgjøret med Haugland.'}
];
function state(s){s.legacyFund??={version:1,id:null,active:false,paid:0,quarters:0,lastQuarter:Math.floor(s.week/13),started:null,lastChange:-100};return s.legacyFund;}
function free(s){return Math.max(0,s.cash-G.capitalReserve(s)-(s.loan?.balance||0));}
G.legacyFundQuote=function(s,id){const m=G.LEGACY_FUNDS.find(m=>m.id===id);if(!m)return null;const a=s.legacyFund||{id:null,active:false,paid:0},initial=a.id===null?8000000:0,reason=s.ended?'Historien er avsluttet.':s.event?'Ta avgjørelsen først.':s.trip?'Fullfør reisen først.':s.rankLevel<5?'Velg arven når du blir Gudfar.':a.id&&a.id!==id?'Du har gitt et annet langsiktig løfte. Du kan sette innbetalingene på pause, men ikke bytte mottaker.':a.active?'Løftet følges allerede opp.':a.id&&s.week-(s.legacyFund?.lastChange??-100)<13?'Vent et kvartal før du gir løftet på nytt.':free(s)<initial?'Behold driftsreserven og gjeldsdekningen, og sett av åtte millioner til første innbetaling.':null;return {...m,initial,quarterly:Math.floor(Math.max(0,free(s)-initial)*m.rate),paid:a.id===id?a.paid:0,reason,valid:!reason};};
G.legacyFundInfo=s=>{const a=state(s),m=G.LEGACY_FUNDS.find(m=>m.id===a.id);return {...a,choice:m||null,nextContribution:m&&a.active?Math.floor(free(s)*m.rate):0,options:G.LEGACY_FUNDS.map(m=>G.legacyFundQuote(s,m.id))};};
G.legacyControl=s=>s.legacyFund?.id==='city'&&s.legacyFund.active&&s.legacyFund.paid>=20000000?1:0;
G.legacyArcBonus=(s,track)=>{const a=s.legacyFund;if(!a?.active)return 0;const applicable=(track==='rival'&&a.id==='crew')||(track==='case'&&a.id==='counsel');return applicable?Math.min(.03,.012*Math.log2(1+a.paid/8000000)):0;};
function pay(s,n,title){const a=state(s);s.cash-=n;a.paid+=n;s.ledger.unshift({day:s.day,week:s.week,title,gross:0,cost:n,net:-n,status:'Varig løfte. Midlene tilhører mottakerne og kan ikke tas ut som privat formue.'});s.ledger=s.ledger.slice(0,120);}
function choose(s,id){const q=G.legacyFundQuote(s,id),a=state(s);a.id=id;a.active=true;a.lastChange=s.week;a.started??=s.day;a.lastQuarter=Math.floor(s.week/13);if(q.initial)pay(s,q.initial,q.name+' / første innbetaling');G.notifyScene(s,{id:'legacy-fund-'+id,kind:'legacy',speaker:q.speaker,title:'Det du lar andre beholde',text:q.text+' Fra nå av går '+Math.round(q.rate*100)+' % av fri kasse til løftet hvert kvartal. Gjeld og driftsreserve holdes utenfor. Innbetalingene kan settes på pause.'});return q.name+'. Første innbetaling '+q.initial.toLocaleString('nb-NO')+' kr. Lederne følger opp kvartalsvis.';}
function week(s){const a=state(s),quarter=Math.floor(s.week/13);if(quarter<=a.lastQuarter)return;a.lastQuarter=quarter;if(!a.active||!a.id||s.ended)return;const m=G.LEGACY_FUNDS.find(m=>m.id===a.id),amount=Math.floor(free(s)*m.rate);if(!amount)return;pay(s,amount,m.name+' / kvartal');a.quarters++;if(a.id==='crew'){s.crew.trained+=Math.min(2,s.crew.members-s.crew.trained);s.crew.loyalty=clamp(s.crew.loyalty+4);s.crew.fatigue=clamp(s.crew.fatigue-5);}if(a.id==='city'){s.influence+=4;if(s.arc?.active)s.arc.support=clamp(s.arc.support+4);}if(a.id==='counsel'&&s.arc?.active){s.arc.defense=clamp(s.arc.defense+4);s.arc.evidence=clamp(s.arc.evidence-2);}if(a.quarters%4===0)G.notifyScene(s,{id:'legacy-year-'+a.quarters,kind:'legacy',speaker:m.speaker,title:'Et år der løftet holdt',text:m.name+'. Mottakerne har fått '+a.paid.toLocaleString('nb-NO')+' kr. Det er en del av byen som fortsetter uten at du eier den.'});}
G.registerSystem({id:'legacyFund',migrate:state,validate(s){if(s.legacyFund===undefined)return true;const a=s.legacyFund;return !!a&&a.version===1&&(a.id===null||G.LEGACY_FUNDS.some(m=>m.id===a.id))&&typeof a.active==='boolean'&&Number.isSafeInteger(a.paid)&&a.paid>=0&&Number.isSafeInteger(a.quarters)&&a.quarters>=0&&a.quarters<=Math.floor(s.week/13)&&Number.isSafeInteger(a.lastChange)&&a.lastChange>=-100&&a.lastChange<=s.week&&Number.isSafeInteger(a.lastQuarter)&&a.lastQuarter>=0&&a.lastQuarter<=Math.floor(s.week/13)&&a.quarters<=a.lastQuarter&&(a.id===null?!a.active&&a.paid===0&&a.quarters===0&&a.started===null:Number.isSafeInteger(a.started)&&a.started>=0&&a.started<=s.day&&a.paid>=8000000);},hooks:{week},actions:{legacyFund:{guard(s,id){const q=G.legacyFundQuote(s,id);return q?q.reason:'Velg et langsiktig løfte.';},handler:choose},legacyPause:{guard(s){if(!state(s).active)return 'Det er ingen løpende innbetaling å pause.';if(G.legacyControl(s)&&Object.keys(s.scale.territories).length>=G.controlLimit(s))return 'Den lokale ledelsen har ansvar for en region. Frigjør en plass før du trekker deg.';},handler(s){state(s).active=false;state(s).lastChange=s.week;return 'Innbetalingene er pauset. Tidligere bidrag tilhører fortsatt mottakerne.';}}}});
if(typeof module!=='undefined')module.exports=G;
})(typeof window!=='undefined'?window:globalThis);
